// Unwrap Supabase array, then EMIT ONE n8n ITEM PER UPLOAD ROW.
// n8n will auto-fan-out subsequent nodes (Get Signed URL, Download PDF, Claude,
// Save Classification) across these items. Each item carries the voucher/tenant
// scope plus the single upload's storage details.
const arr = $input.first().json;
if (!Array.isArray(arr) || arr.length === 0) {
  throw new Error('Voucher not found');
}
const v = arr[0];
const uploads = Array.isArray(v.uploads) ? v.uploads : [];
if (uploads.length === 0) {
  throw new Error('Voucher has no uploads to classify');
}

return uploads.map((u) => ({
  json: {
    voucher_id: v.id,
    tenant_id:  v.tenant_id,
    project_id: v.project_id,
    voucher:    v,
    upload: {
      id:             u.id,
      storage_path:   u.storage_path,
      storage_bucket: u.storage_bucket || 'Document submission',
      filename:       u.filename,
      declared_kind:  u.declared_kind || null,
      mime_type:      u.mime_type || 'application/pdf'
    }
  }
}));

// Build the Anthropic /v1/messages body for ONE PDF.
// The PDF lands in $binary.data after the Download step (responseFormat: file).
// n8n stores binaries with a base64 'data' field already — we pass that
// straight into the document.source.data block.
const item = $input.first();
const bin = item.binary && item.binary.data;
if (!bin || !bin.data) {
  throw new Error('No binary PDF on this item');
}
const base64 = bin.data; // already base64 per n8n convention

// Carry forward the upload context from the Unwrap node via the item's json,
// which n8n preserves across HTTP nodes when responseFormat=file is used.
const ctx = $node['Unwrap + Emit Upload Items'].json;
// In a fan-out, $node['Unwrap + Emit Upload Items'].json is the FIRST item's
// json only — so we must rely on $json carried by the request chain. Since
// the Download node's json is the signed-URL response, we instead re-read
// the upload context from the current item's json (Get Signed URL preserves
// the input json fields alongside signedURL on a 4.2 HTTP node when no
// JSON body replaces them — but to be safe we pull from $items() of the
// Unwrap node at the same pairedItem index).
const pairedIndex = item.pairedItem && typeof item.pairedItem === 'object'
  ? (Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : item.pairedItem.item)
  : (typeof item.pairedItem === 'number' ? item.pairedItem : 0);
const allUnwrapped = $items('Unwrap + Emit Upload Items');
const src = allUnwrapped[pairedIndex || 0] && allUnwrapped[pairedIndex || 0].json;
if (!src) {
  throw new Error('Could not resolve upload context for paired item ' + pairedIndex);
}

const userText = 'Classify this document and extract its key fields. The document is in Arabic. Return JSON only — no prose, no markdown, no code fences. Use the exact JSON shape described in the system prompt. Field NAMES must be in English; field VALUES that come from the document should be preserved in Arabic where appropriate (e.g., supplier_name_ar, description_ar, items_received_ar). Numeric values must be parsed to numbers. Dates use ISO format YYYY-MM-DD when determinable.';

const system = 'You are a document-extraction agent for Saudi real-estate escrow auditing. The document attached is in Arabic. Classify it into ONE of these categories:\n  voucher | invoice | completion_certificate | contractor_extract | signed_approval | receipt_confirmation | supplier_contract | supplier_ledger | bank_statement | other | unknown\n\nReturn ONLY this JSON object — no prose, no markdown, no code fences:\n{\n  "classified_kind": <one of the categories above>,\n  "classification_confidence": <number 0..1>,\n  "summary_en": <one short English sentence describing what the document is>,\n  "summary_ar": <one short Arabic sentence describing what the document is>,\n  "extracted_fields": { ...type-specific fields per the schema below... }\n}\n\nExtracted-field schemas by classified_kind:\n\n* invoice → { invoice_number, invoice_date, supplier_name_ar, supplier_name_en, total_sar, vat_sar, issued_to (developer name as it appears), line_items: [ { description_ar, description_en, unit, qty, unit_price, line_total } ] }\n* voucher → { voucher_number, voucher_date, total_sar, beneficiary_name, expense_nature_hint, signed_by }\n* completion_certificate → { certificate_number, issued_date, completion_pct, issued_by_name, contract_referenced }\n* contractor_extract → { extract_number, extract_date, claimed_completion_pct, project_referenced, total_claimed_sar }\n* signed_approval → { signer_name, signer_title, date_signed, approval_subject }\n* receipt_confirmation → { receipt_date, items_received_ar, confirmed_by_name }\n* supplier_contract → { contract_number, contract_date, supplier, total_value_sar }\n* supplier_ledger → { ledger_period, entries: [ { date, invoice_number, debit, credit, balance } ] }\n* bank_statement → { period_start, period_end, account_number, total_credits, total_debits }\n* other | unknown → {} (summary fields above are sufficient)\n\nWhen a field is not present in the document, set it to null rather than guessing. Be conservative with classification_confidence: only use values above 0.9 when the document is unambiguous (clear header, standard format).';

const claude_body = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 4000,
  system,
  messages: [
    {
      role: 'user',
      content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
        { type: 'text', text: userText }
      ]
    }
  ]
};

return [{
  json: {
    voucher_id: src.voucher_id,
    tenant_id:  src.tenant_id,
    project_id: src.project_id,
    upload:     src.upload,
    claude_body
  }
}];

// Parse Claude's per-PDF JSON. Mirror Phase 1's robust JSON extractor.
const item = $input.first();
const claudeResp = item.json;
const text = (claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text) || '';
const tokensIn  = claudeResp.usage?.input_tokens  ?? 0;
const tokensOut = claudeResp.usage?.output_tokens ?? 0;

function extractJSON(s) {
  const stripped = s.trim().replace(/^```(json)?/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(stripped); } catch (e) {}
  const first = stripped.indexOf('{');
  const last  = stripped.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(stripped.slice(first, last + 1)); } catch (e) {}
  }
  throw new Error('Claude returned non-JSON: ' + s.slice(0, 200));
}

const parsed = extractJSON(text);

// Recover upload context via pairedItem → Build Claude Message node.
const pairedIndex = item.pairedItem && typeof item.pairedItem === 'object'
  ? (Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : item.pairedItem.item)
  : (typeof item.pairedItem === 'number' ? item.pairedItem : 0);
const built = $items('Build Claude Message');
const src = built[pairedIndex || 0] && built[pairedIndex || 0].json;
if (!src) {
  throw new Error('Could not resolve build-msg context for paired item ' + pairedIndex);
}

const allowed = ['voucher','invoice','completion_certificate','contractor_extract','signed_approval','receipt_confirmation','supplier_contract','supplier_ledger','bank_statement','other','unknown'];
const kind = allowed.includes(parsed.classified_kind) ? parsed.classified_kind : 'unknown';

return [{
  json: {
    voucher_id: src.voucher_id,
    tenant_id:  src.tenant_id,
    project_id: src.project_id,
    upload_id:  src.upload.id,
    filename:   src.upload.filename,
    declared_kind: src.upload.declared_kind,
    classified_kind: kind,
    classification_confidence: typeof parsed.classification_confidence === 'number' ? parsed.classification_confidence : null,
    summary_en: parsed.summary_en || '',
    summary_ar: parsed.summary_ar || '',
    extracted_fields: parsed.extracted_fields || {},
    tokens_in:  tokensIn,
    tokens_out: tokensOut
  }
}];

// AGGREGATION STRATEGY
// --------------------
// The fan-out from "Unwrap + Emit Upload Items" produces one execution branch
// per upload. n8n re-executes every downstream node once per item. To collect
// ALL parallel iterations into a single row, this node uses $items('Parse
// Claude per-PDF') which returns the FULL array of upload-level results in
// one shot — n8n only fires this node after all upstream items have settled.
// We do NOT need a Merge node: $items() naturally serialises the fan-out.
//
// Bucketing: we split per-upload extractions by classified_kind so the audit
// prompt below can reference them by name (voucher, invoice_extracts, etc.).

const per = $items('Parse Claude per-PDF').map(i => i.json);
if (!per.length) {
  throw new Error('No per-upload extractions to aggregate');
}

const voucher_extracted    = per.find(x => x.classified_kind === 'voucher') || null;
const invoice_extracts     = per.filter(x => x.classified_kind === 'invoice');
const cert_extracts        = per.filter(x => x.classified_kind === 'completion_certificate');
const extract_extracts     = per.filter(x => x.classified_kind === 'contractor_extract');
const approval_extracts    = per.filter(x => x.classified_kind === 'signed_approval');
const receipt_extracts     = per.filter(x => x.classified_kind === 'receipt_confirmation');
const contract_extracts    = per.filter(x => x.classified_kind === 'supplier_contract');
const ledger_extracts      = per.filter(x => x.classified_kind === 'supplier_ledger');
const bank_statement_extracts = per.filter(x => x.classified_kind === 'bank_statement');
const other_extracts       = per.filter(x => x.classified_kind === 'other' || x.classified_kind === 'unknown');

const scope = $items('Unwrap + Emit Upload Items')[0]?.json || {};

const extractions = per.map(x => ({
  upload_id: x.upload_id,
  filename:  x.filename,
  classified_kind: x.classified_kind,
  classification_confidence: x.classification_confidence,
  summary_en: x.summary_en,
  summary_ar: x.summary_ar,
  extracted_fields: x.extracted_fields
}));

const total_tokens_in  = per.reduce((s, x) => s + (x.tokens_in  || 0), 0);
const total_tokens_out = per.reduce((s, x) => s + (x.tokens_out || 0), 0);

return [{
  json: {
    voucher_id: scope.voucher_id,
    tenant_id:  scope.tenant_id,
    project_id: scope.project_id,
    voucher:    scope.voucher,
    extractions,
    voucher_extracted,
    invoice_extracts,
    cert_extracts,
    extract_extracts,
    approval_extracts,
    receipt_extracts,
    contract_extracts,
    ledger_extracts,
    bank_statement_extracts,
    other_extracts,
    extraction_tokens_in:  total_tokens_in,
    extraction_tokens_out: total_tokens_out
  }
}];

// Merge aggregated extractions + master data into one audit context object.
const agg = $node['Aggregate Per-Upload Results'].json;
const contracts = $node['Fetch Contracts'].json || [];
const certs     = $node['Fetch Completion Certificates'].json || [];
const prior     = $node['Fetch Prior Vouchers'].json || [];

return [{
  json: {
    voucher_id: agg.voucher_id,
    tenant_id:  agg.tenant_id,
    project_id: agg.project_id,
    voucher:    agg.voucher,
    contracts,
    completion_certificates: certs,
    prior_vouchers: prior,
    extracted: {
      extractions:               agg.extractions,
      voucher_extracted:         agg.voucher_extracted,
      invoice_extracts:          agg.invoice_extracts,
      cert_extracts:             agg.cert_extracts,
      extract_extracts:          agg.extract_extracts,
      approval_extracts:         agg.approval_extracts,
      receipt_extracts:          agg.receipt_extracts,
      contract_extracts:         agg.contract_extracts,
      ledger_extracts:           agg.ledger_extracts,
      bank_statement_extracts:   agg.bank_statement_extracts,
      other_extracts:            agg.other_extracts
    },
    extraction_tokens_in:  agg.extraction_tokens_in,
    extraction_tokens_out: agg.extraction_tokens_out
  }
}];

// Parse Claude's audit JSON, prep batch insert for agent_checks, compute verdict counts.
const claudeResp = $input.first().json;
const text = (claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text) || '';
const tokensIn  = claudeResp.usage?.input_tokens  ?? 0;
const tokensOut = claudeResp.usage?.output_tokens ?? 0;

function extractJSON(s) {
  const stripped = s.trim().replace(/^```(json)?/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(stripped); } catch (e) {}
  const first = stripped.indexOf('{');
  const last  = stripped.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(stripped.slice(first, last + 1)); } catch (e) {}
  }
  throw new Error('Claude returned non-JSON: ' + s.slice(0, 200));
}

const parsed = extractJSON(text);
const checks = Array.isArray(parsed.checks) ? parsed.checks : [];
let pass = 0, fail = 0, warn = 0;
for (const c of checks) {
  if (c.status === 'pass') pass++;
  else if (c.status === 'fail') fail++;
  else if (c.status === 'warn' || c.status === 'needs_info') warn++;
}

const ctx = $node['Build Audit Context'].json;
const run = $node['Create Agent Run'].json[0];

const checkRows = checks.map((c, i) => ({
  tenant_id: ctx.tenant_id,
  agent_run_id: run.id,
  voucher_id: ctx.voucher_id,
  order_index: i + 1,
  rule_code:     c.rule_code     ?? `RULE_${String(i+1).padStart(2,'0')}_UNKNOWN`,
  rule_title_en: c.rule_title_en ?? c.rule_code ?? `Rule ${i+1}`,
  rule_title_ar: c.rule_title_ar ?? null,
  severity:      c.severity      ?? 'blocking',
  status:        c.status        ?? 'needs_info',
  evidence_quote:  c.evidence_quote  ?? null,
  expected_value:  c.expected_value  ?? null,
  actual_value:    c.actual_value    ?? null,
  ai_confidence:   typeof c.ai_confidence === 'number' ? c.ai_confidence : null,
  reasoning:       c.reasoning ?? null,
}));

return [{
  json: {
    voucher_id: ctx.voucher_id,
    tenant_id:  ctx.tenant_id,
    project_id: ctx.project_id,
    agent_run_id: run.id,
    overall_verdict: parsed.overall_verdict || 'needs_review',
    summary: parsed.summary || '',
    pass_count: pass,
    fail_count: fail,
    warn_count: warn,
    tokens_in:  tokensIn  + (ctx.extraction_tokens_in  || 0),
    tokens_out: tokensOut + (ctx.extraction_tokens_out || 0),
    check_rows: checkRows,
    submitted_by_external_email: ctx.voucher?.submitted_by_external_email ?? null,
  }
}];

// Map overall_verdict → voucher.status.
const v = $node['Parse Claude + Build Inserts'].json.overall_verdict;
let status = 'needs_review';
if (v === 'approved') status = 'needs_review';   // even on AI pass, a human still approves
else if (v === 'rejected') status = 'rejected';
else status = 'needs_review';
return [{ json: { ...$json, next_voucher_status: status } }];

