  html: '<h2>Voucher audit complete (Phase 2 — PDF + Arabic)</h2><p><strong>Verdict:</strong> ' + $node['Parse Claude + Build Inserts'].json.overall_verdict + '</p><p><strong>Pass:</strong> ' + $node['Parse Claude + Build Inserts'].json.pass_count + ' · <strong>Fail:</strong> ' + $node['Parse Claude + Build Inserts'].json.fail_count + ' · <strong>Warn/Needs info:</strong> ' + $node['Parse Claude + Build Inserts'].json.warn_count + '</p><p>' + $node['Parse Claude + Build Inserts'].json.summary + '</p><p><a href="https://app.fullscope.sa/app/escrow/' + $node['Parse Claude + Build Inserts'].json.project_id + '/vouchers/' + $node['Parse Claude + Build Inserts'].json.voucher_id + '">Open voucher in Full Scope →</a></p>'
}) }}
